const extractChatTargets = (text = '', team = []) => {
  const normalized = text.toLowerCase();
  if (/@all\b/i.test(text)) return ['all'];
  const tokenTargets = [...text.matchAll(/@([A-Za-z0-9_-]+)/g)].map(match => match[1].toLowerCase());
  return Array.from(new Set(team
    .filter(agent => {
      const name = String(agent.name || '').toLowerCase();
      const id = String(agent.id || '').toLowerCase();
      return (name && normalized.includes(`@${name}`))
        || (id && normalized.includes(`@${id}`))
        || tokenTargets.includes(id)
        || name.split(/\s+/).some(part => tokenTargets.includes(part));
    })
    .map(agent => agent.name)));
};

const chatTypeForRecoveredProof = (type = '', eventType = '') => {
  if (type === 'role-question') return 'question';
  if (eventType === 'change-confirmed' || eventType === 'leader-confirmed') return 'decision';
  if (eventType === 'assignment-acknowledged' || eventType === 'peer-handoff-ack' || eventType === 'work-pulse' || eventType === 'daily-report') return 'progress';
  if (eventType === 'leader-assignment' || eventType === 'peer-handoff' || eventType === 'change-sync' || eventType === 'change-discussion') return 'mention';
  return 'text';
};

const CHAT_PROOF_ID_PATTERN = /^(msg_|m_|chat_|agent_chat_|agent_message_|agent_work_|agent_management_|agent_management_response_|worker_chat_|room_|transcript_channel_created_|transcript_channel_pin_|transcript_channel_pin_message_|transcript_pin_|transcript_pin_message_|transcript_reply_|transcript_reply_message_|transcript_mention_|transcript_mention_message_|transcript_attachment_|transcript_attachment_message_|u_|multi_channel_change_|manager_demo_|manager_ui_dual_change_|manager_change_composer_|manager_assignment_composer_|manager_ui_agent_message_|director_brief_|decision_|system_.*_kickoff|leader_bid_|leader_assign_|leader_ack_|assign_|ack_|role_negotiation_|change_discuss_|change_confirm_|change_sync_|peer_handoff_|peer_handoff_ack_)/;
const KICKOFF_MEETING_TRANSCRIPT_ID_PATTERN = /^kickoff_meeting_[^_]+_(director_brief|director_clarification|role_\d+|leader_\d+|candidate_)/;

const isChatProofId = (id = '') => {
  const value = String(id || '');
  return CHAT_PROOF_ID_PATTERN.test(value) || KICKOFF_MEETING_TRANSCRIPT_ID_PATTERN.test(value);
};

const chatProofIdsFromIds = (ids = []) => Array.from(new Set(
  (Array.isArray(ids) ? ids : [ids]).filter(Boolean).filter(isChatProofId)
));

const chatProofIdsFromRow = (row = {}) => Array.from(new Set([
  row.messageId,
  row.message?.id,
  row.sourceMessageId,
  row.requestMessageId,
  row.confirmationMessageId,
  row.syncMessageId,
  ...(row.chatProofIds || []),
  ...(row.messageIds || []),
  ...(row.sourceMessageIds || []),
  ...(row.discussionMessageIds || []),
  ...chatProofIdsFromIds(row.proofIds || []),
].filter(Boolean).filter(isChatProofId)));

const chatProofIdsFromAttachment = (attachment = {}) => Array.from(new Set([
  attachment.messageId,
  attachment.providerEvidenceMessageId,
  ...(attachment.providerEvidenceMessageIds || []),
  ...(attachment.chatProofIds || []),
  ...(attachment.messageIds || []),
  ...chatProofIdsFromIds(attachment.proofIds || []),
].filter(Boolean).filter(isChatProofId)));

const CHAT_ATTACHMENT_TEXT_LIMIT = 24 * 1024;

const transcriptProofIdsFromRow = (row = {}) => Array.from(new Set([
  ...(row.messages || []).map(message => message.id),
  ...(row.archivedProofIds || []),
  ...(row.proofIds || []),
].filter(Boolean)));

const chatProofIdsFromNode = (node = {}) => Array.from(new Set([
  node.messageId,
  node.sourceMessageId,
  node.requestMessageId,
  node.confirmationMessageId,
  node.syncMessageId,
  ...(node.chatProofIds || []),
  ...(node.messageIds || []),
  ...(node.sourceMessageIds || []),
  ...(node.discussionMessageIds || []),
  ...(node.attachments || []).flatMap(attachment => chatProofIdsFromAttachment(attachment)),
  ...(node.proofIds || []).filter(isChatProofId),
].filter(Boolean).filter(isChatProofId)));

const formatRecoveredProofTime = (value) => {
  if (!value) return 'Recovered Proof';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return 'Recovered Proof';
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
};

const recoverProofMessages = (project = {}, proofIds = [], fallbackChannelId = 'main') => {
  const wanted = new Set(proofIds.filter(Boolean));
  if (!wanted.size) return [];

  const recovered = new Map();
  const addRecovered = (message) => {
    if (!message?.id || !wanted.has(message.id) || recovered.has(message.id) || !isConversationMessage(message)) return;
    recovered.set(message.id, {
      projectId: project.id,
      channelId: message.channelId || fallbackChannelId || 'main',
      type: message.type || 'text',
      author: message.author || 'Agent',
      role: message.role || '',
      time: message.time || 'Recovered Proof',
      text: message.text || 'Recovered project proof message.',
      recoveredProof: true,
      ...message,
    });
  };

  [
    ...(project.initiation?.directorBriefId ? [{
      id: project.initiation.directorBriefId,
      type: 'director-brief',
      speaker: 'Director',
      role: 'Project Owner',
      text: project.initiation?.summary || project.currentObjective || project.objective || project.name || '',
      hears: (project.team || []).map(agent => agent.id),
    }] : []),
    ...(project.initiation?.roleNegotiation?.transcript || []),
    ...(project.initiation?.leaderElection?.transcript || []),
    ...(project.initiation?.managerClarifications || []),
  ].forEach(item => addRecovered({
    id: item.id,
    channelId: 'main',
    type: item.type === 'director-clarification' || item.type === 'director-brief' ? 'decision' : chatTypeForRecoveredProof(item.type),
    author: item.speaker || item.author || 'Agent',
    role: item.role || '',
    time: item.type === 'leader-campaign' ? 'Leader Election' : 'Kickoff',
    text: item.text,
    targets: item.hears || item.hearsOthers || [],
    weight: item.type === 'director-clarification' ? 'Director Clarification' : item.weight,
  }));

  return Array.from(recovered.values());
};

const BROWSER_STORAGE_WARNING_EVENT = 'hof-browser-storage-warning';

const reportBrowserStorageIssue = ({ operation, key, error }) => {
  if (typeof window === 'undefined') return;
  const detail = {
    operation,
    key,
    message: error?.message || String(error || 'Browser storage is unavailable.'),
  };
  window.__HOF_BROWSER_STORAGE_WARNING__ = detail;
  if (typeof window.dispatchEvent === 'function' && typeof CustomEvent === 'function') {
    window.dispatchEvent(new CustomEvent(BROWSER_STORAGE_WARNING_EVENT, { detail }));
  }
};

const readStoredJson = (key, fallback) => {
  if (typeof window === 'undefined') return fallback;
  try {
    const stored = window.localStorage.getItem(key);
    return stored ? JSON.parse(stored) : fallback;
  } catch (error) {
    reportBrowserStorageIssue({ operation: 'read', key, error });
    return fallback;
  }
};

const writeStoredJson = (key, value) => {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(key, JSON.stringify(value));
  } catch (error) {
    reportBrowserStorageIssue({ operation: 'write', key, error });
  }
};

const loadBackendBaseUrl = () => {
  if (typeof window !== 'undefined' && window.__AGENT_BACKEND_URL__) {
    return isValidBackendBaseUrl(window.__AGENT_BACKEND_URL__)
      ? normalizeBackendBaseUrl(window.__AGENT_BACKEND_URL__)
      : DEFAULT_AGENT_BACKEND_URL;
  }
  const storedBackendUrl = readStoredJson(STORAGE_KEYS.backendUrl, null);
  return isValidBackendBaseUrl(storedBackendUrl)
    ? normalizeBackendBaseUrl(storedBackendUrl)
    : DEFAULT_AGENT_BACKEND_URL;
};

const loadProjectNavigation = () => restoreProjectNavigationSnapshot(
  readStoredJson(STORAGE_KEYS.projectNavigationSnapshot, null),
  loadBackendBaseUrl(),
);

const loadLocalAuthSession = () => {
  if (typeof window === 'undefined') return null;
  let sessionSession = null;
  let persistentSession = null;
  try {
    sessionSession = JSON.parse(window.sessionStorage.getItem(STORAGE_KEYS.localAuthSession) || 'null');
  } catch {
    sessionSession = null;
  }
  try {
    persistentSession = JSON.parse(window.localStorage.getItem(STORAGE_KEYS.localAuthSession) || 'null');
  } catch {
    persistentSession = null;
  }
  const { session: stored, persistence } = selectStoredLocalAuthSession({
    sessionSession,
    persistentSession,
  });
  if (!stored?.token || !isValidBackendBaseUrl(stored.baseUrl)) return null;
  return {
    token: String(stored.token),
    baseUrl: normalizeBackendBaseUrl(stored.baseUrl),
    user: stored.user || null,
    expiresAt: stored.expiresAt || null,
    persistence,
  };
};

const hasConfiguredBackendBaseUrl = () => {
  if (typeof window !== 'undefined') {
    if (isValidBackendBaseUrl(window.__AGENT_BACKEND_URL__)) return true;
    try {
      const storedBackendUrl = window.localStorage.getItem(STORAGE_KEYS.backendUrl);
      if (storedBackendUrl !== null) return isValidBackendBaseUrl(JSON.parse(storedBackendUrl));
    } catch {
      return false;
    }
    return isValidBackendBaseUrl(DEFAULT_AGENT_BACKEND_URL) && isLocalNetworkEndpoint(DEFAULT_AGENT_BACKEND_URL);
  }
  return isValidBackendBaseUrl(DEFAULT_AGENT_BACKEND_URL) && isLocalNetworkEndpoint(DEFAULT_AGENT_BACKEND_URL);
};

const defaultProviderRuntimeStatus = () => ({
  running: false,
  lastRunAt: null,
  baseUrl: loadBackendBaseUrl(),
  modelProvider: null,
  searchProvider: null,
  secretVaultStatus: null,
  secretVaultRecords: null,
  providerVaultBindings: null,
  settingsProviderReadiness: null,
  settingsRuntimeReadiness: null,
  settingsIntegrationReadiness: null,
  localMvpStartupReadiness: null,
  projectId: null,
  modelTest: null,
  searchTest: null,
  error: null,
});

const loadProviderRuntimeStatus = () => {
  const fallback = defaultProviderRuntimeStatus();
  const stored = readStoredJson(STORAGE_KEYS.providerRuntimeStatus, null);
  if (!stored || typeof stored !== 'object') return fallback;
  if (normalizeBackendBaseUrl(stored.baseUrl || DEFAULT_AGENT_BACKEND_URL) !== normalizeBackendBaseUrl(fallback.baseUrl)) {
    return fallback;
  }
  return {
    ...fallback,
    ...stored,
    running: false,
    modelTest: null,
    searchTest: null,
    error: null,
  };
};

const persistProviderRuntimeStatus = (status = {}) => {
  if (!status || typeof status !== 'object' || status.running) return;
  writeStoredJson(STORAGE_KEYS.providerRuntimeStatus, {
    lastRunAt: status.lastRunAt || null,
    baseUrl: normalizeBackendBaseUrl(status.baseUrl || DEFAULT_AGENT_BACKEND_URL),
    modelProvider: status.modelProvider || null,
    searchProvider: status.searchProvider || null,
    secretVaultStatus: status.secretVaultStatus || null,
    secretVaultRecords: status.secretVaultRecords || null,
    providerVaultBindings: status.providerVaultBindings || null,
    settingsProviderReadiness: status.settingsProviderReadiness || null,
    settingsRuntimeReadiness: status.settingsRuntimeReadiness || null,
    settingsIntegrationReadiness: status.settingsIntegrationReadiness || null,
    localMvpStartupReadiness: status.localMvpStartupReadiness || null,
    projectId: status.projectId || null,
  });
};

